"use client";

import Engine from "./curtain-slider-engine.jsx";
import css from "./curtain-slider-styles";

export interface CurtainSlide {
  src: string;
  alt?: string;
  title: string;
  label?: string;
}
export interface CurtainSliderProps {
  className?: string;
  images?: CurtainSlide[];
  duration?: number;
  ease?: string;
  columns?: number;
  auto?: number;
  drag?: boolean;
  stagger?: number;
  disable?: string;
  onChange?: (event: { index: number; direction: number; slide: CurtainSlide }) => void;
}

export function CurtainSlider(props: CurtainSliderProps) {
  return (
    <>
      <style>{css}</style>
      <Engine {...props} />
    </>
  );
}

import type { CurtainSliderProps } from "./curtain-slider";
import type { ComponentType } from "react";
declare const Engine: ComponentType<CurtainSliderProps>;
export default Engine;
